"""landscape_manuscript.py (19 ต.ค. 2026) เติมตารางผู้สมัคร benchmark ใน manuscript/data-section-draft.tex จาก out/benchmark_candidates.csv

แก้เฉพาะบรรทัดระหว่าง marker
  % >>> landscape-candidates rows (generated by build/landscape_manuscript.py; do not edit by hand)
  % <<< landscape-candidates rows
ข้อความรอบตาราง (prose, \\toon{}, \\claudedraft{}) ไม่ถูกแตะ  ตัวเลขใน prose ตรวจโดย build/consistency_check.py
รัน: python3 build/landscape_manuscript.py [--check]   (--check = ไม่เขียน แค่บอกว่าตรงไหม)
"""
import csv, json, os, sys
HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(HERE)
TEX = "manuscript/data-section-draft.tex"
B, E = "% >>> landscape-candidates rows (generated by build/landscape_manuscript.py; do not edit by hand)", "% <<< landscape-candidates rows"
C = list(csv.DictReader(open("out/benchmark_candidates.csv", encoding="utf-8")))
R3 = {k: v for k, v in json.load(open("out/reconcile_counts.json", encoding="utf-8"))["name_frequencies"].items() if isinstance(v, dict)}
G = {"frequently used benchmark": "F", "potential diversity candidate": "D", "requires verification": "V"}
def tt(s): return s.replace("_", "\\_").replace("&", "\\&").replace("%", "\\%")
def rng(v):
    x = [float(a) for a in v.split(";") if a]
    return "--" if not x else (f"{x[0]:,.0f}" if len(x) == 1 else f"{min(x):,.0f}--{max(x):,.0f}")
def rows():
    sel = [c for c in C if c["listed_in_task"] == "yes" or c["group"] != "frequently used benchmark"]
    out = []
    for c in sel:
        fam = c["family_papers"]  # rule T1 for every row (28 Oct 2026); no separate R3/heuristic marks
        inst = rng(c["n_instances_values"]) + ("$^{a}$" if c["name"] == "shuttle" else "")
        cls = tt(c["n_classes_values"].replace(";", ", ")) or "--"
        out.append(f'\\texttt{{{tt(c["name"])}}} & {G[c["group"]]} & {c["papers"]} & {fam} & {inst} & {c["n_instances_printed"]}/{c["entries"]} & {cls} & {c["modified_entries"]}/{c["entries"]}\\\\')
    return out
tex = open(TEX, encoding="utf-8").read()
if tex.count(B) != 1 or tex.count(E) != 1: sys.exit("STOP: markers missing or duplicated in " + TEX)
i, j = tex.index(B) + len(B), tex.index(E)
new = "\n" + "\n".join(rows()) + "\n"
if "--check" in sys.argv:
    print("rows match csv" if tex[i:j] == new else "ROWS DIFFER from out/benchmark_candidates.csv"); sys.exit(0 if tex[i:j] == new else 1)
if tex[i:j] != new:
    open(TEX, "w", encoding="utf-8").write(tex[:i] + new + tex[j:]); print("table rows updated:", len(rows()))
else: print("table rows already current:", len(rows()))
